import React, { useState, useEffect } from "react";
import { FaTrashAlt } from "react-icons/fa";
import { useLocation, useNavigate } from "react-router-dom";
import products from "../data/product.json";
import "./Cart.css";

const Cart = () => {
  const navigate = useNavigate();
  const location = useLocation();

  // Initialize cart with sample data from Product.json
    const [cartItems, setCartItems] = useState(
    products.slice(0, 6).map(item => ({
        ...item,
        quantity: 1,
        selected: false
    }))
    );


  useEffect(() => {
    if (location.state?.removeItems) {
      const idsToRemove = location.state.removeItems.map(item => item.id);
      setCartItems(prev => prev.filter(item => !idsToRemove.includes(item.id)));
      window.history.replaceState({}, document.title);
    }
  }, [location.state]);

  const handleIncrease = id => {
    setCartItems(cartItems.map(item =>
      item.id === id ? { ...item, quantity: item.quantity + 1 } : item
    ));
  };

  const handleDecrease = id => {
    setCartItems(cartItems.map(item =>
      item.id === id && item.quantity > 1
        ? { ...item, quantity: item.quantity - 1 }
        : item
    ));
  };

  const handleQuantityChange = (id, value) => {
    const qty = parseInt(value) || 1;
    setCartItems(cartItems.map(item =>
      item.id === id ? { ...item, quantity: qty } : item
    ));
  };

  const handleRemove = id => {
    setCartItems(cartItems.filter(item => item.id !== id));
  };

  const handleSelect = id => {
    setCartItems(cartItems.map(item =>
      item.id === id ? { ...item, selected: !item.selected } : item
    ));
  };

  const handleSelectAll = checked => {
    setCartItems(cartItems.map(item => ({ ...item, selected: checked })));
  };

  const selectedItems = cartItems.filter(item => item.selected);
  const totalPrice = selectedItems.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );

  const allSelected =
    cartItems.length > 0 && cartItems.every(item => item.selected);

  const handleCheckout = () => {
    if (selectedItems.length === 0) {
      alert("Please select at least one item before proceeding to checkout.");
      return;
    }

    navigate("/checkout", { state: { cartItems: selectedItems } });
  };

  return (
    <div className="cart-container">
      <h2 className="cart-title">Shopping Cart</h2>

      {cartItems.length === 0 ? (
        <div className="no-items">No items in your cart.</div>
      ) : (
        <>
          <div className="cart-list-wrapper">
            <div className="cart-list">
              {cartItems.map(item => (
                <div key={item.id} className="cart-item">
                  <input
                    type="checkbox"
                    checked={item.selected}
                    onChange={() => handleSelect(item.id)}
                    className="cart-checkbox"
                  />
                  <img src={item.image} alt={item.name} className="cart-image" />
                  <div className="cart-details">
                    <p className="cart-name">{item.name}</p>
                    <p className="cart-price" style={{ color: "#FF7E0D" }}>
                      ₱{item.price}
                    </p>
                  </div>
                  <div className="cart-actions">
                    <button onClick={() => handleDecrease(item.id)} className="qty-btn">-</button>
                    <input
                      type="text"
                      value={item.quantity}
                      onChange={e => handleQuantityChange(item.id, e.target.value)}
                      className="qty-input"
                    />
                    <button onClick={() => handleIncrease(item.id)} className="qty-btn">+</button>
                  </div>
                  <FaTrashAlt className="trash-icon" onClick={() => handleRemove(item.id)} />
                </div>
              ))}
            </div>
          </div>

          <div className="cart-footer">
            <div className="footer-left">
              <label className="select-all">
                <input
                  type="checkbox"
                  checked={allSelected}
                  onChange={e => handleSelectAll(e.target.checked)}
                />
                Select All
              </label>
            </div>
            <div className="footer-right">
              <p className="cart-total">
                TOTAL: <span style={{ color: "#FF7E0D" }}>₱{totalPrice}</span>
              </p>
              <button className="checkout-btn" onClick={handleCheckout}>
                Check Out
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default Cart;
